%Reads the size of the FNper Matrix
% [lin,~] = size(FNper);
[~,col] = size(FNper);

%Corrects vector order if thrust vector is backwards
% if FNper(1,lin) < FNper(1,1)
if FNper(1,col) < FNper(1,1)
        
    A  =  fliplr(A);
    B  =  fliplr(B);
    C  =  fliplr(C);
    D  =  fliplr(D);   
    
